import{_ as a,o as t,c as s,a3 as o}from"./chunks/framework.DWfJTVRq.js";const u=JSON.parse('{"title":"Several processes","description":"Several processes can have one database file open at once, each reading and writing it, with nothing to set up and nothing to clean up after a process dies.","frontmatter":{"title":"Several processes","order":8,"prev":{"text":"Encryption","link":"/guide/encryption"},"next":{"text":"Tools","link":"/guide/tools"}},"headers":[{"level":2,"title":"How they share a file","slug":"how-they-share-a-file","link":"#how-they-share-a-file","children":[]},{"level":2,"title":"Rules that come with the locks","slug":"rules-that-come-with-the-locks","link":"#rules-that-come-with-the-locks","children":[]},{"level":2,"title":"Within one process","slug":"within-one-process","link":"#within-one-process","children":[]}],"relativePath":"guide/processes.md","filePath":"en/guide/processes.md","lastUpdated":1791015517000}'),n={name:"guide/processes.md"};function i(r,e,h,l,c,d){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="several-processes" tabindex="-1">Several processes <a class="header-anchor" href="#several-processes" aria-label="Permalink to &quot;Several processes&quot;">​</a></h1><p>Several processes can have one database file open at once, each reading and writing it, with nothing to set up and nothing to clean up after a process dies.</p><h2 id="how-they-share-a-file" tabindex="-1">How they share a file <a class="header-anchor" href="#how-they-share-a-file" aria-label="Permalink to &quot;How they share a file&quot;">​</a></h2><ul><li>Each process sees the others&#39; commits as soon as they are made.</li><li>One process writes at a time, and a reader never waits for a writer.</li><li>A write waits for a writer in another process as it does for one in its own, up to the busy timeout, and then fails with <code>BUSY</code>.</li><li>A writer that has waited a moment gets the next turn, so a process that commits in a tight loop cannot keep the others out.</li></ul><p>The processes coordinate through the operating system&#39;s file locks and nothing else: no shared memory, no lock file, no server. A process that dies at any moment, holding any lock, releases it as it dies, and the others carry on. <a href="./../engine/locking">Locking</a> in the Engine section describes the locks.</p><h2 id="rules-that-come-with-the-locks" tabindex="-1">Rules that come with the locks <a class="header-anchor" href="#rules-that-come-with-the-locks" aria-label="Permalink to &quot;Rules that come with the locks&quot;">​</a></h2><ul><li><strong>Local disks only.</strong> The locks, and the syncs a commit waits for, work only on a local disk. A database on a network file system such as NFS or SMB is refused with <code>UNSUPPORTED_FILE_SYSTEM</code>.</li><li><strong>Do not open the file a second way.</strong> Nothing else in a process that has a database open may open its file, not even to copy it: on Linux and macOS, closing that second handle drops the locks the database holds. To copy a database that is open, use a <a href="./tools#back-up-a-file">backup</a>.</li><li><strong>iOS App Group containers.</strong> An app whose database lives in an App Group container has to close it before the app is suspended, because iOS ends a suspended app that holds a lock there.</li></ul><h2 id="within-one-process" tabindex="-1">Within one process <a class="header-anchor" href="#within-one-process" aria-label="Permalink to &quot;Within one process&quot;">​</a></h2><p>Opening a file that is already open in the process gives another handle to the same database: the handles share one page cache and one writer, and the engine keeps one operating-system handle for the file. Each handle keeps the schema it was opened with, and fails with <code>SCHEMA_MISMATCH</code> once another handle or process has migrated the file.</p><div class="lang-only" data-code-lang="node"><p>In Electron, several instances of the app, or the main process and a utility process, share a file the same way. <a href="./electron">Electron</a> has what is particular to it.</p></div><div class="lang-only" data-code-lang="dart"><p>In a Flutter app, several isolates share a file the same way: each opens its own <code>Database</code>, and the handles share the process&#39;s page cache and writer. An isolate&#39;s asynchronous writes take turns with each other; another isolate&#39;s write waits for them in the engine, as another process&#39;s would.</p></div>',11)])])}const w=a(n,[["render",i]]);export{u as __pageData,w as default};
